gOW(){return"\u0648\u06d5\u06a9 \u0695\u06c6\u0698\u06cc \u06a9\u0627\u0631 \u0646\u0627\u0698\u0645\u06ce\u0631\u062f\u0631\u06ce\u0646\u060c \u0648 \u0626\u0627\u06af\u0627\u062f\u0627\u0631\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5 \u062f\u06d5\u0631\u062f\u06d5\u06a9\u06d5\u0648\u06ce\u062a \u06a9\u0627\u062a\u06ce\u06a9 \u063a\u06cc\u0627\u0628\u06ce\u06a9 \u062f\u06d5\u06a9\u06d5\u0648\u06ce\u062a\u06d5 \u0633\u06d5\u0631\u06cc\u0627\u0646. \u06af\u06c6\u0695\u0627\u0646\u06a9\u0627\u0631\u06cc \u0644\u06d5\u0633\u06d5\u0631 \u0645\u0627\u0646\u06af\u06d5 \u0646\u0648\u06ce\u06cc\u06d5\u06a9\u0627\u0646\u06cc \u0645\u0648\u0648\u0686\u06d5 \u062c\u06ce\u0628\u06d5\u062c\u06ce \u062f\u06d5\u0628\u06ce\u062a\u060c \u0648 \u0644\u06d5\u0633\u06d5\u0631 \u0645\u0627\u0646\u06af\u06ce\u06a9\u06cc \u0647\u06d5\u0628\u0648\u0648 \u06a9\u0627\u062a\u06ce\u06a9 \u063a\u06cc\u0627\u0628\u06ce\u06a9\u06cc \u062a\u06ce\u062f\u0627 \u0632\u06cc\u0627\u062f \u06cc\u0627\u0646 \u0644\u0627\u0628\u0628\u0631\u06ce\u062a."},
Iz(a,b){return"\u063a\u06cc\u0627\u0628\u06d5\u06a9\u0627\u0646: "+a+" \u0695\u06c6\u0698 \xb7 \u2212"+b},
