gTb(){return"\u0647\u0627\u062a\u06d5 \u067e\u06d5\u0633\u06d5\u0646\u062f\u06a9\u0631\u0646"},
gTc(){return"\u0686\u0627\u06a4\u06d5\u0695\u06ce\u06cc \u067e\u06ce\u062f\u0627\u0686\u0648\u0648\u0646\u0627 Meta"},
gTd(){return"Meta \u0695\u06d5\u062a \u06a9\u0631"},
gEY(){return"\u0646\u06d5\u0647\u0627\u062a\u06cc\u06cc\u06d5 \u0686\u06ce\u06a9\u0631\u0646"},
gT6(){return"\u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u0628\u067e\u0634\u06a9\u0646\u06d5"},
gEX(){return"\u0698\u06ce\u06a4\u06d5\u06a9\u0631\u0646\u0627 \u0648\u0627\u062a\u0633\u0627\u0628\u06ce"},
gT1(){return"\u0648\u0627\u062a\u0633\u0627\u0628 \u0698\u06ce\u06a4\u06d5 \u0628\u06cc\u062a\u061f"},
T0(a){return a+" \u0628\u06d5\u0631\u0633\u06a4\u0627 \u0646\u06d5\u062e\u06c6\u0634\u0627\u0646 \u0646\u0627\u062f\u06d5\u062a \u0648 \u06af\u0631\u06ce\u062f\u0627\u0646\u06ce\u0646 \u0648\u0627\u062a\u0633\u0627\u0628\u06ce \u06cc\u06ce\u0646 \u0648\u0627\u0646 \u062f\u0647\u06ce\u0646\u06d5 \u0698\u06ce\u0628\u0631\u0646. \u0646\u06d5\u062e\u06c6\u0634 \u0648 \u0633\u06d5\u0631\u06d5\u062f\u0627\u0646\u06ce\u0646 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06ce \u06a9\u0627\u0631\u062a\u06ce\u06a9\u0631\u0646 \u0644 \u0633\u06d5\u0631 \u0646\u0627\u0628\u06cc\u062a."},
gEr(){return"\u0648\u0627\u062a\u0633\u0627\u0628"},
